function v3_report_e4(T,out)
frequencies=[.02 .04 .06 .08 .1 .12 .15 .18 .2];for field={'gain_db','phase_lag_deg'},key=field{1};f=figure('Visible','off');tiledlayout(1,3);for a=[1 3 5],nexttile;hold on;for method={'MPC_surface','PID_CHAIN_CMG','MPC_joint'},name=method{1};if strcmp(name,'MPC_surface'),S=T(T.amplitude_deg==a & ~T.cmg,:);elseif strcmp(name,'PID_CHAIN_CMG'),S=T(T.amplitude_deg==a & strcmp(T.method,'PID_CHAIN_CMG'),:);else,S=T(T.amplitude_deg==a & T.cmg & strcmp(T.method,'MPC'),:);end;[~,order]=sort(S.frequency_Hz);plot(S.frequency_Hz(order),S.(key)(order),'-o','Color',v3_color(name),'DisplayName',name);if strcmp(key,'phase_lag_deg'),bad=logical(S.phase_unreliable);if any(bad),scatter(S.frequency_Hz(bad),S.(key)(bad),40,'x','MarkerEdgeColor',[.65 .1 .1],'HandleVisibility','off');end;end;end;xlabel('Frequency (Hz)');if strcmp(key,'gain_db'),ylabel('Fundamental gain (dB)');else,ylabel('Phase lag (deg)');end;title(sprintf('A=%d deg',a));legend('Interpreter','none','Location','best');grid on;end;if strcmp(key,'phase_lag_deg'),sgtitle('Crosses: phase unreliable when gain ratio < 0.05');end;v3_savefig(f,out,['E4_' key]);end
f=figure('Visible','off');tiledlayout(1,3);maxerror=max(T.pitch_rmse_deg,[],'omitnan');if isempty(maxerror)||~isfinite(maxerror)||maxerror<=0,maxerror=1;end;for method=1:3,Z=nan(3,9);for ai=1:3,amp=[1 3 5];for fi=1:9,if method==1,mask=~T.cmg;elseif method==2,mask=strcmp(T.method,'PID_CHAIN_CMG');else,mask=T.cmg & strcmp(T.method,'MPC');end;k=find(mask & T.amplitude_deg==amp(ai) & abs(T.frequency_Hz-frequencies(fi))<1e-9,1);if ~isempty(k),Z(ai,fi)=T.pitch_rmse_deg(k);end;end;end;nexttile;im=imagesc(Z,[0 maxerror]);set(im,'AlphaData',isfinite(Z));set(gca,'Color',[.8 .8 .8]);set(gca,'YTick',1:3,'YTickLabel',[1 3 5],'XTick',1:9,'XTickLabel',frequencies);labels={'Surface MPC','Frozen PID + CMG','Joint MPC'};title(labels{method});xlabel('Frequency (Hz)');ylabel('Amplitude (deg)');bar=colorbar;bar.Label.String='Pitch RMSE (deg)';end;v3_savefig(f,out,'E4_RMSE');writetable(T(:,{'id','method','amplitude_deg','frequency_Hz','analysis_start_s','analysis_end_s','qbar_min_Pa','qbar_max_Pa','V_min_mps','V_max_mps','alpha_min_deg','alpha_max_deg','height_min_m','height_max_m','qbar_relative_range','height_relative_range'}),fullfile(out,'tables','E4_flight_condition_audit.csv'));
for hz=[.1 .15],S=T(T.amplitude_deg==1 & abs(T.frequency_Hz-hz)<1e-9,:);if ~isempty(S),v3_e4_anomaly(S,out,hz);end;end
end
